import { createSlice, createAsyncThunk } from "@reduxjs/toolkit";
import contractService from "../services/contractService";
import { uniqBy } from "lodash";

const initialState = {
  contracts: [],
  isError: false,
  isSuccess: false,
  isLoading: false,
  message: "",
  next_page_param: null,
  updateContractByUuid: {
    isLoading: false,
  },
  generateGLContract: {
    isLoading: false,
  },
  exceedPayments: [],
  exceedBankStatement: [],
  updateAPLByUuid: {
    isLoading: false,
  },
};

export const createContracts = createAsyncThunk(
  "contracts/create",
  async (data, thunkAPI) => {
    try {
      return await contractService.createContracts(data);
    } catch (error) {
      const message =
        (error.response &&
          error.response.data &&
          error.response.data.message) ||
        error.message ||
        error.toString();
      return thunkAPI.rejectWithValue(message);
    }
  }
);

export const getContracts = createAsyncThunk(
  "contracts",
  async ({ params, firstFetch = true }, thunkAPI) => {
    try {
      const response = await contractService.getContracts(params);

      const {
        metadata: { info },
      } = response;

      const remainingPages = Math.ceil(
        ((+info?.total || 0) - (+info?.offset || 0)) / +info?.limit || 10
      );

      const next_page_param =
        remainingPages >= 1
          ? {
            ...params,
            offset: (+info?.limit || 10) + (+info?.offset || 0),
          }
          : null;
      return {
        info: info,
        data: response.data,
        firstFetch,
        next_page_param,
      };
    } catch (error) {
      const message =
        (error.response &&
          error.response.data &&
          error.response.data.message) ||
        error.message ||
        error.toString();
      return thunkAPI.rejectWithValue(message);
    }
  }
);

